def equations_possible(equations):
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        parent[find(a)] = find(b)

    for eq in equations:
        a, op, _, b = eq
        if op == '=':
            union(a, b)

    for eq in equations:
        a, op, _, b = eq
        if op == '!':
            if find(a) == find(b):
                return False
    return True

